  'md.auton': 'ᱪᱟᱹᱞᱩ: ᱡᱚᱛᱚ ᱥᱮᱣ ᱨᱮ {name} ᱯᱷᱚᱞᱰᱟᱨ ᱨᱮ {file} ᱟᱯᱰᱮᱴ ᱦᱩᱭᱩᱜᱼᱟ᱾', 'md.autoask': 'ᱠᱚᱢᱯᱤᱭᱩᱴᱟᱨ ᱫᱚᱦᱲᱟ ᱪᱟᱹᱞᱩ ᱞᱮᱠᱷᱟᱱ ᱵᱨᱟᱣᱡᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱫᱚᱦᱲᱟ ᱟᱢᱟᱜ ᱦᱩᱠᱩᱢ ᱞᱟᱹᱠᱛᱤ ᱠᱟᱱᱟ᱾',
