  'doc.invoice': 'ᱤᱱᱵᱷᱚᱭᱮᱥ', 'docs.invoice': 'ᱤᱱᱵᱷᱚᱭᱮᱥ', 'Doc.invoice': 'ᱤᱱᱵᱷᱚᱭᱮᱥ',
