  'my.title': 'ᱥᱮᱴᱤᱝ ᱟᱨ ᱥᱮᱣ ᱟᱠᱟᱱ ᱰᱮᱴᱟ', 'my.intro': 'Nivesh Sahayak ᱨᱮᱭᱟᱜ ᱡᱚᱛᱚ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱴᱩᱞ ᱢᱤᱫ ᱡᱟᱭᱜᱟ ᱠᱷᱚᱱ ᱥᱮᱴ ᱢᱮ: ᱟᱢᱟᱜ ᱵᱤᱡᱱᱮᱥ, ᱜᱨᱟᱦᱟᱠ ᱟᱨ ᱥᱚᱯᱞᱟᱭᱟᱨ, ᱟᱭᱴᱮᱢ ᱟᱨ ᱥᱟᱨᱵᱷᱤᱥ, ᱱᱚᱢᱵᱟᱨᱤᱝ ᱟᱨ ᱰᱤᱯᱷᱚᱞᱴ᱾ ᱡᱚᱛᱚ ᱱᱚᱶᱟ ᱵᱨᱟᱣᱡᱟᱨ ᱨᱮ ᱜᱮ ᱛᱟᱦᱮᱸᱱᱟ᱾ ᱟᱞᱮ ᱴᱷᱮᱱ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱠᱩᱞᱚᱜᱼᱟ᱾',
