  "c.si30": "ᱱᱚᱶᱟ ᱥᱮᱞᱯᱷ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱨᱮᱭᱟᱜ ᱛᱟᱨᱤᱠ ᱫᱚ ᱡᱤᱱᱤᱥ ᱥᱮ ᱥᱟᱨᱵᱷᱤᱥ ᱧᱟᱢ ᱛᱟᱭᱚᱢ 30 ᱫᱤᱱ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱠᱟᱱᱟ᱾ ᱱᱤᱭᱚᱢ ᱞᱮᱠᱟ 30 ᱫᱤᱱ ᱵᱷᱤᱛᱚᱨ ᱵᱮᱱᱟᱣ ᱞᱟᱹᱠᱛᱤ᱾ ᱛᱚᱵᱮ ᱦᱚᱸ ᱥᱮᱣ ᱢᱮ?",
