  "g3.note": "CGST Act ᱨᱮᱭᱟᱜ section 49 ᱟᱨ Rule 88A ᱞᱮᱠᱟ ᱥᱮᱴ-ᱚᱯᱷ: ᱯᱮᱨᱮᱡ IGST ᱠᱨᱮᱰᱤᱴ ᱵᱮᱵᱷᱟᱨ ᱦᱩᱭᱩᱜᱼᱟ, ᱩᱱᱛᱮ CGST ᱟᱨ SGST/UTGST ᱠᱨᱮᱰᱤᱴ; CGST ᱟᱨ SGST ᱠᱨᱮᱰᱤᱴ ᱫᱚ ᱢᱤᱫ ᱯᱟᱱᱛᱮ ᱵᱟᱝ ᱵᱮᱵᱷᱟᱨ ᱦᱩᱭᱩᱜᱼᱟ; ᱨᱤᱵᱷᱟᱨᱥ ᱪᱟᱨᱡ ᱴᱮᱠᱥ ᱱᱟᱜᱫ ᱨᱮ ᱮᱢ ᱦᱩᱭᱩᱜᱼᱟ᱾ ᱯᱚᱨᱴᱟᱞ ᱫᱚ ᱯᱷᱟᱭᱤᱞ ᱚᱠᱛᱚ ᱨᱮ ᱢᱩᱪᱟᱹᱫ ᱥᱮᱴ-ᱚᱯᱷ ᱛᱮᱭᱟᱨ ᱮᱫᱟ᱾",
  "g3.w.zr": "ᱵᱤᱞ {no} ᱫᱚ ᱮᱠᱥᱯᱳᱨᱴ ᱥᱮ SEZ ᱵᱤᱞ ᱠᱟᱱᱟ, ᱢᱮᱱᱠᱷᱟᱱ CGST/SGST ᱫᱮᱠᱷᱟᱣ ᱠᱟᱱᱟ᱾ ᱡᱤᱨᱳ ᱨᱮᱴ ᱥᱚᱯᱞᱟᱭ ᱨᱮ IGST ᱜᱮ ᱞᱟᱹᱜᱩᱜᱼᱟ᱾",
  "g3.w.rcmv": "ᱣᱟᱹᱪᱟᱹᱨ {no}: ᱨᱤᱵᱷᱟᱨᱥ ᱪᱟᱨᱡ ᱴᱮᱠᱥ CGST + SGST ᱞᱮᱠᱟ ᱧᱟᱢ ᱟᱠᱟᱱᱟ᱾ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱮᱴᱟᱜ ᱨᱟᱡᱽᱭᱚ ᱨᱮ ᱠᱷᱟᱱ (IGST) ᱯᱮᱴᱷᱟ ᱠᱚ ᱵᱚᱫᱚᱞ ᱢᱮ᱾",
  "g3.w.nogstin": "{p} ᱠᱷᱚᱱ ᱯᱩᱨᱪᱮᱥ ᱵᱤᱞ {no} ᱨᱮ ᱴᱷᱤᱠ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ GSTIN ᱵᱟᱝ ᱢᱮᱱᱟᱜᱼᱟ, ᱚᱱᱟᱛᱮ ᱩᱱᱤᱭᱟᱜ ITC GSTR-2B ᱨᱮ ᱵᱟᱝ ᱧᱮᱞᱚᱜᱼᱟ᱾",
  "g3.w.2b": "4(A)(5) ᱯᱮᱴᱷᱟ ᱨᱮᱭᱟᱜ ITC ᱥᱮᱣ ᱟᱠᱟᱱ ᱯᱩᱨᱪᱮᱥ ᱵᱤᱞ ᱟᱨ ᱠᱷᱚᱨᱚᱪ ᱠᱷᱚᱱ ᱛᱟᱦᱮᱱ ᱠᱟᱱᱟ᱾ GSTR-2B ᱨᱮ ᱧᱮᱞ ᱠᱟᱱ ᱜᱮ ᱠᱞᱮᱢ ᱢᱮ; ᱩᱱᱤ ᱠᱷᱚᱱ ᱠᱚᱢ ᱠᱷᱟᱱ GSTR-2B ᱨᱮᱭᱟᱜ ᱟᱸᱠᱰᱟ ᱚᱞ ᱢᱮ᱾",
  "g3.w.neg": "ᱢᱮᱱᱟᱜ ᱠᱨᱮᱰᱤᱴ ᱫᱚ ᱡᱤᱨᱳ ᱠᱷᱚᱱ ᱠᱚᱢ ᱠᱟᱱᱟ: ᱨᱤᱵᱷᱟᱨᱥᱟᱞ ᱫᱚ ᱠᱨᱮᱰᱤᱴ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱠᱟᱱᱟ᱾ ᱵᱷᱮᱰ ᱫᱚ ᱱᱟᱜᱫ ᱨᱮ ᱮᱢ ᱞᱟᱹᱠᱛᱤ; ᱟᱢᱟᱜ ᱟᱠᱟᱣᱱᱴᱮᱱᱴ ᱫᱚᱦᱚ ᱢᱮ᱾",
