  "g2.h.ok": "ᱢᱤᱫ ᱜᱮ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ, ᱱᱚᱢᱵᱚᱨ, ᱯᱮᱴᱷᱟ ᱟᱨ ᱛᱟᱨᱤᱠ᱾ ᱱᱚᱶᱟ ᱠᱨᱮᱰᱤᱴ ᱠᱞᱮᱢ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱟᱱᱟ᱾",
