  "g2.h.numdiff": "ᱢᱤᱫ ᱜᱮ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱟᱨ ᱯᱮᱴᱷᱟ, ᱢᱮᱱᱠᱷᱟᱱ ᱵᱤᱞ ᱱᱚᱢᱵᱚᱨ ᱮᱴᱟᱜ ᱞᱮᱠᱟ ᱚᱞ ᱟᱠᱟᱱᱟ᱾ ᱛᱟᱭᱚᱢ ᱴᱟᱭᱤᱯ ᱵᱷᱮᱰ ᱠᱟᱱᱟ: ᱟᱢᱟᱜ ᱮᱱᱴᱨᱤ ᱴᱷᱤᱠ ᱢᱮ᱾",
  "g2.h.only2b": "ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱱᱚᱶᱟ ᱵᱤᱞ ᱠᱚ ᱨᱤᱯᱳᱨᱴ ᱠᱟᱱᱟ, ᱢᱮᱱᱠᱷᱟᱱ ᱟᱢᱟᱜ ᱵᱩᱠ ᱨᱮ ᱥᱮᱣ ᱵᱟᱝ ᱟᱠᱟᱱᱟ᱾ ᱟᱢ ᱥᱟᱱᱟᱢ ᱥᱮ ᱥᱮᱵᱟ ᱧᱟᱢ ᱠᱟᱱ ᱠᱷᱟᱱ ᱮᱱᱴᱨᱤ ᱮᱢ ᱢᱮ, ᱥᱮ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱞᱟᱹᱜᱤᱫ ᱴᱷᱤᱠ ᱠᱟᱹᱢᱤ ᱢᱮ᱾",
  "g2.h.onlybooks": "ᱱᱚᱶᱟ ᱛᱟᱨᱤᱠ ᱨᱮᱭᱟᱜ ᱟᱢᱟᱜ ᱵᱤᱞ ᱠᱚ ᱡᱟᱦᱟᱸ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱱᱤᱛᱚᱜ ᱨᱤᱯᱳᱨᱴ ᱵᱟᱝ ᱟᱠᱟᱱᱟ᱾ GSTR-2B ᱨᱮ ᱵᱟᱝ ᱧᱮᱞᱚᱜ ᱠᱷᱟᱱ ITC ᱠᱞᱮᱢ ᱵᱟᱝ ᱢᱮ; ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱫᱚᱦᱚ ᱢᱮ᱾",
  "g2.h.noitc": "ᱯᱚᱨᱴᱟᱞ ᱫᱚ ᱡᱟᱦᱟᱸ ᱵᱤᱞ ᱨᱮ ITC ᱵᱟᱝ ᱢᱮᱱᱟᱜᱼᱟ ᱢᱮᱱᱛᱮ ᱫᱮᱠᱷᱟᱣ ᱠᱟᱱᱟ (ᱩᱫᱟᱹᱞ ᱞᱟᱹᱜᱤᱫ ᱥᱚᱯᱞᱟᱭ ᱴᱷᱟᱶ ᱥᱚᱯᱞᱟᱭᱟᱹᱨᱤ ᱨᱟᱡᱽᱭᱚ ᱨᱮ, ᱥᱮ ᱚᱠᱛᱚ ᱥᱤᱢᱟ)᱾",
