  "c8.w.near": "ᱟᱢ ᱠᱚᱢᱯᱚᱡᱤᱥᱚᱱ ᱥᱤᱢᱟ ᱨᱮᱭᱟᱜ 80% ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱵᱮᱵᱷᱟᱨ ᱟᱠᱟᱱᱟ᱾ ᱯᱷᱤᱱᱛᱟᱣ ᱠᱟᱹᱢᱤ ᱢᱮ: ᱥᱤᱢᱟ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱛᱮ ᱥᱟᱫᱷᱟᱨᱚᱬ ᱥᱠᱤᱢ ᱨᱮ ᱦᱟᱡᱽ ᱞᱟᱹᱠᱛᱤ᱾",
