  "td.no.c": "TDS ᱵᱟᱝ: ᱱᱚᱶᱟ ᱵᱤᱞ ₹30,000 ᱥᱮ ᱩᱱᱤ ᱠᱷᱚᱱ ᱠᱚᱢ ᱠᱟᱱᱟ ᱟᱨ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱡᱚᱛᱚ ₹1,00,000 ᱵᱷᱤᱛᱤᱨ ᱨᱮ ᱛᱟᱦᱮᱱ ᱠᱟᱱᱟ᱾",
  "td.no.m": "TDS ᱵᱟᱝ: ᱢᱟᱦᱟ ᱨᱮᱭᱟᱜ ᱮᱢ {l} ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱵᱟᱝ ᱠᱟᱱᱟ᱾",
  "td.no.y": "TDS ᱱᱟᱜᱟᱹᱛ ᱵᱟᱝ: ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱡᱚᱛᱚ {l} ᱵᱷᱤᱛᱤᱨ ᱨᱮ ᱛᱟᱦᱮᱱ ᱠᱟᱱᱟ᱾ ᱩᱱᱟ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱛᱮ ᱮᱢ ᱨᱮ ᱠᱟᱴᱚᱜ ᱢᱮ᱾",
  "td.no.q": "TDS ᱱᱟᱜᱟᱹᱛ ᱵᱟᱝ: ᱱᱚᱶᱟ ᱥᱮᱨᱢᱟ ᱨᱮ ᱱᱚᱶᱟ ᱵᱮᱪᱮᱭᱟᱹ ᱠᱷᱚᱱ ᱠᱷᱟᱹᱛᱮ {l} ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱵᱟᱝ ᱠᱟᱱᱟ᱾",
  "td.catch": "ᱱᱚᱶᱟ ᱮᱢ ᱛᱮ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱡᱚᱛᱚ ᱥᱤᱢᱟ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱦᱩᱭ ᱞᱮᱱᱟ, ᱚᱱᱟᱛᱮ TDS ᱫᱚ ᱡᱚᱛᱚ ᱛᱮ ᱦᱤᱥᱟᱹᱵ ᱦᱩᱭᱩᱜᱼᱟ, TDS ᱵᱟᱝ ᱛᱮ ᱯᱟᱹᱦᱤᱞ ᱮᱢ ᱟᱠᱟᱱ {y} ᱥᱮᱞᱮᱫ᱾ ᱡᱩᱫᱤ ᱩᱱᱤ ᱨᱮᱭᱟᱜ ᱢᱤᱫ ᱛᱷᱚᱲᱟ ᱨᱮ ᱯᱟᱹᱦᱤᱞ ᱜᱮ TDS ᱠᱟᱴ ᱟᱠᱟᱱ ᱠᱷᱟᱱ, ᱵᱷᱮᱰ ᱜᱮ ᱠᱟᱴᱚᱜ ᱢᱮ᱾",
  "td.nopan": "ᱴᱷᱤᱠ PAN ᱵᱟᱝ ᱠᱷᱟᱱ ᱨᱮᱴ ᱫᱚ 20% ᱥᱮ ᱥᱟᱫᱷᱟᱨᱚᱬ ᱨᱮᱴ ᱨᱮᱭᱟᱜ ᱵᱟᱨᱭᱟ ᱜᱩᱱᱟ, ᱪᱮᱫ ᱵᱟᱹᱲᱛᱤ ᱠᱟᱱᱟ (ᱥᱟᱱᱟᱢ ᱠᱷᱟᱹᱛᱮ ᱞᱟᱹᱜᱤᱫ 5%)᱾ ᱯᱟᱹᱛᱤᱭᱟᱹ ᱦᱚᱲ ᱠᱷᱚᱱ PAN ᱤᱛᱩ ᱢᱮ᱾",
  "td.trans": "ᱞᱚᱰ ᱠᱟᱹᱢᱤᱭᱟᱹ ᱡᱟᱦᱟᱸ ᱨᱮᱭᱟᱜ 10 ᱥᱮ ᱩᱱᱤ ᱠᱷᱚᱱ ᱠᱚᱢ ᱥᱟᱱᱟᱢ ᱞᱚᱰ ᱜᱟᱲᱤ ᱛᱟᱦᱮᱱ ᱟᱨ PAN ᱥᱟᱶ ᱜᱚᱲᱚ ᱨᱮᱭᱟᱜ ᱚᱞ ᱮᱢ ᱠᱷᱟᱱ TDS ᱵᱟᱝ ᱛᱮ ᱮᱢ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱟᱱᱟ᱾",
  "td.q": "ᱟᱢᱟᱜ ᱯᱟᱧᱡᱟᱭ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱴᱚᱨᱱᱚᱵᱷᱚᱨ ₹10 ᱠᱨᱚᱲ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱛᱟᱦᱮᱱ ᱠᱷᱟᱱ ᱜᱮ ᱠᱟᱴᱚᱜ ᱢᱮ, ᱟᱨ ᱱᱚᱶᱟ ᱵᱮᱪᱮᱭᱟᱹ ᱠᱷᱚᱱ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ₹50 ᱞᱟᱠᱷ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱠᱷᱟᱹᱛᱮ ᱨᱮ ᱜᱮ᱾",
  "td.ib": "ᱴᱮᱠᱥ ᱚᱰᱤᱴ ᱵᱟᱝ ᱟᱠᱟᱱ ᱢᱤᱫ ᱦᱚᱲ ᱠᱷᱚᱱ ᱮᱢ ᱟᱠᱟᱱ ᱵᱷᱟᱲᱟ ᱨᱮ, TDS ᱢᱤᱫ ᱪᱷᱟᱯᱟ ᱜᱮ ᱠᱟᱴᱚᱜᱼᱟ, ᱥᱮᱨᱢᱟ ᱥᱮ ᱵᱷᱟᱲᱟ ᱨᱮᱭᱟᱜ ᱢᱩᱪᱟᱹᱫ ᱢᱟᱦᱟ ᱨᱮᱭᱟᱜ ᱵᱷᱟᱲᱟ ᱠᱷᱚᱱ᱾",
  "td.oldnote": "1 ᱮᱯᱨᱤᱞ 2026 ᱠᱷᱚᱱ ᱥᱟᱱᱟᱢ ᱮᱢ ᱞᱟᱹᱜᱤᱫ Income-tax Act, 1961 ᱞᱟᱹᱜᱩᱜᱼᱟ: ᱯᱩᱨᱟᱹᱢ section ᱱᱚᱢᱵᱚᱨ ᱵᱮᱵᱷᱟᱨ ᱢᱮ᱾",
  "td.h.reg": "ᱟᱢ ᱠᱟᱴ ᱟᱠᱟᱱ TDS (ᱟᱢᱟᱜ ᱮᱢ ᱣᱟᱹᱪᱟᱹᱨ ᱠᱷᱚᱱ)",
  "td.h.regh": "voucher.niveshsahayak.in ᱥᱮ ᱮᱯ ᱨᱮ TDS ᱨᱮᱴ ᱥᱟᱶ ᱥᱮᱣ ᱟᱠᱟᱱ ᱣᱟᱹᱪᱟᱹᱨ, ᱢᱟᱦᱟ ᱟᱨ section ᱞᱮᱠᱟ, ᱡᱚᱢᱟ ᱢᱟᱦᱴᱟ ᱥᱟᱶ᱾",
