  "b1.tcsh": "ᱚᱠᱟ ᱟᱠᱨᱤᱧ ᱨᱮ ᱟᱠᱨᱤᱧᱤᱡ ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱦᱟᱛᱟᱣ ᱞᱟᱹᱠᱛᱤᱭᱟ ᱚᱱᱟ ᱨᱮ ᱜᱮ: ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱟᱹᱭᱤᱱ 2025 ᱥᱮᱠᱥᱚᱱ 394 (ᱢᱟᱲᱟᱝ ᱥᱮᱠᱥᱚᱱ 206C)᱾ ᱯᱷᱟᱭᱤᱱᱟᱱᱥ ᱟᱹᱭᱤᱱ 2026 ᱛᱟᱭᱚᱢ ᱨᱮᱴ: ᱫᱟᱨᱩ, ᱠᱮᱸᱫ ᱥᱟᱠᱟᱢ, ᱠᱟᱴ ᱥᱮ ᱵᱤᱨ ᱡᱤᱱᱤᱥ, ᱥᱠᱨᱮᱯ, ᱠᱚᱭᱞᱟ, ᱞᱤᱜᱽᱱᱟᱭᱤᱴ ᱥᱮ ᱞᱩᱦᱟ ᱠᱷᱟᱱᱤᱡ 2%; ₹10 ᱞᱟᱠᱷ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱜᱟᱹᱰᱤ ᱥᱮ ᱱᱚᱴᱤᱯᱷᱟᱭᱤᱰ ᱡᱤᱱᱤᱥ 1%; ᱵᱤᱫᱮᱥ ᱴᱩᱨ ᱯᱮᱠᱮᱡ 2%; ᱯᱟᱨᱠᱤᱝ, ᱴᱚᱞ ᱯᱞᱟᱡᱟ, ᱠᱷᱟᱱ 2%᱾ 1 ᱠᱷᱚᱱ 5 ᱡᱤᱱᱤᱥ ᱨᱮ TCS ᱵᱟᱹᱱᱩᱜᱼᱟ ᱡᱩᱫᱤ ᱠᱤᱱᱤᱡᱤᱡ ᱚᱞ ᱠᱟᱛᱮ ᱮᱢᱟ ᱡᱮ ᱡᱤᱱᱤᱥ ᱵᱮᱱᱟᱣ ᱞᱟᱹᱜᱤᱫ, ᱵᱮᱯᱟᱨ ᱞᱟᱹᱜᱤᱫ ᱫᱚ ᱵᱟᱝ᱾ ᱮᱴᱟᱜ ᱡᱤᱱᱤᱥ ᱨᱮ TCS ᱵᱟᱹᱱᱩᱜᱼᱟ (₹50 ᱞᱟᱠᱷ ᱨᱮᱭᱟᱜ ᱢᱟᱨᱮ ᱱᱤᱭᱚᱢ ᱵᱟᱹᱱᱩᱜᱼᱟ)᱾",
  "b1.tcssec": "ᱥᱮᱠᱥᱚᱱ ᱟᱨ ᱪᱮᱫ ᱨᱮ",
  "b1.tcsrate": "TCS ᱨᱮᱴ (%)",
  "b1.tcsrh": "ᱪᱮᱛᱟᱱ ᱨᱮ ᱪᱮᱫ ᱨᱮ ᱵᱟᱪᱷᱟᱣ ᱛᱮ ᱨᱮᱴ ᱟᱹᱭᱤᱱ ᱠᱷᱚᱱ ᱯᱮᱨᱮᱡᱚᱜᱼᱟ; ᱟᱢ ᱵᱚᱫᱚᱞ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ᱾",
  "b1.tcsbase": "TCS ᱪᱮᱫ ᱨᱮ",
