  "b1.tcs_tax": "ᱴᱮᱠᱥᱮᱵᱚᱞ ᱵᱷᱮᱞᱭᱩ (GST ᱵᱮᱜᱚᱨ)",
  "b1.sumtcs": "TCS {v}",
  "b1.v_chg": "ᱵᱟᱹᱲᱛᱤ ᱪᱟᱨᱡ ᱨᱮᱭᱟᱜ ᱧᱩᱛᱩᱢ ᱚᱞ ᱢᱮ, ᱡᱮᱞᱮᱠᱟ ᱵᱷᱟᱲᱟ᱾",
  "b1.v_tcs": "TCS ᱨᱮᱴ ᱚᱞ ᱢᱮ, ᱥᱮ TCS ᱴᱤᱠ ᱚᱪᱚᱜ ᱢᱮ᱾",
  "b1.v_tcs10": "ᱜᱟᱹᱰᱤ ᱥᱮ ᱱᱚᱴᱤᱯᱷᱟᱭᱤᱰ ᱡᱤᱱᱤᱥ ᱨᱮ TCS ᱫᱚ ᱮᱴᱟᱜ ᱢᱤᱫ ᱟᱭᱴᱚᱢ ᱨᱮᱭᱟᱜ ᱜᱚᱱᱚᱝ ₹10 ᱞᱟᱠᱷ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱛᱟᱦᱮᱸ ᱠᱷᱟᱱ ᱜᱮ (ᱱᱚᱴᱤᱯᱷᱤᱠᱮᱥᱚᱱ 36/2025 ᱨᱮ CBDT FAQ, 23 ᱮᱯᱨᱤᱞ 2025)᱾ ᱱᱚᱶᱟ ᱵᱤᱞ ᱨᱮ ᱚᱱᱟ ᱞᱮᱠᱟᱱ ᱟᱭᱴᱚᱢ ᱵᱟᱹᱱᱩᱜᱼᱟ᱾ TCS ᱴᱤᱠ ᱚᱪᱚᱜ ᱢᱮ᱾",
  "b1.c_tcs10g": "GST ᱵᱟᱹᱱᱩᱜ ᱠᱷᱟᱱ ᱡᱟᱦᱟᱱ ᱟᱭᱴᱚᱢ ₹10 ᱞᱟᱠᱷ ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱵᱟᱝ, GST ᱥᱮᱞᱮᱫ ᱠᱷᱟᱱ ᱜᱮ ᱵᱟᱹᱲᱛᱤ᱾ ᱮᱠᱴ ᱨᱮ \"ᱵᱷᱮᱞᱭᱩ\" ᱚᱞ ᱢᱮᱱᱟᱜᱼᱟ ᱟᱨ ᱱᱚᱶᱟ ᱞᱤᱢᱤᱴ ᱨᱮ GST ᱞᱮᱠᱷᱟ ᱦᱩᱭᱩᱜ ᱥᱮ ᱵᱟᱝ ᱡᱟᱦᱟᱱ ᱥᱟᱨᱠᱩᱞᱟᱨ ᱵᱟᱝ ᱴᱷᱤᱠ ᱟᱠᱟᱫᱟ᱾ ᱱᱚᱶᱟ ᱵᱤᱞ ᱨᱮ TCS ᱦᱟᱛᱟᱣ ᱦᱚᱪᱚ ᱥᱮ?",
  "b1.tcsbh": "CBDT ᱥᱟᱨᱠᱩᱞᱟᱨ 17/2020 (ᱯᱮᱨᱟ 4.6.1, ᱢᱟᱨᱮ ᱥᱮᱠᱥᱚᱱ 206C ᱞᱟᱹᱜᱤᱫ): TCS ᱧᱟᱢ ᱟᱠᱟᱱ ᱴᱟᱠᱟ ᱨᱮ GST ᱥᱟᱶ ᱦᱟᱛᱟᱣᱚᱜᱼᱟ, GST, ᱰᱤᱥᱠᱟᱩᱱᱴ ᱥᱮ ᱨᱤᱴᱚᱨᱱ ᱞᱟᱹᱜᱤᱫ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱠᱚᱢᱚᱜᱼᱟ᱾ ᱴᱮᱠᱥᱮᱵᱚᱞ ᱵᱷᱮᱞᱭᱩ ᱟᱢᱟᱜ CA ᱢᱮᱱ ᱠᱷᱟᱱ ᱜᱮ ᱵᱟᱪᱷᱟᱣ ᱢᱮ᱾",
  "b1.cntcs": "ᱵᱤᱞ {no} ᱨᱮ {v} TCS ᱛᱟᱦᱮᱸ ᱠᱟᱱᱟ᱾ ᱱᱚᱶᱟ ᱠᱨᱮᱰᱤᱴ ᱱᱚᱴ ᱚᱱᱟ TCS ᱵᱟᱝ ᱠᱚᱢᱚᱣᱟᱭ: CBDT ᱥᱟᱨᱠᱩᱞᱟᱨ 17/2020 (ᱯᱮᱨᱟ 4.6.1) ᱞᱮᱠᱟᱛᱮ ᱥᱮᱞᱥ ᱨᱤᱴᱚᱨᱱ ᱨᱮ ᱡᱟᱦᱟᱱ ᱮᱰᱡᱟᱥᱴᱢᱮᱱᱴ ᱵᱟᱹᱱᱩᱜᱼᱟ᱾ ᱠᱤᱱᱤᱡᱤᱡ ᱫᱚ ᱱᱚᱶᱟ TCS ᱟᱡᱟᱜ ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱨᱤᱴᱚᱨᱱ ᱨᱮ ᱠᱞᱮᱢ ᱮ ᱠᱟᱹᱢᱤᱭᱟ᱾",
  "b1.tcspan": "ᱠᱤᱱᱤᱡᱤᱡ ᱨᱮᱭᱟᱜ PAN",
  "b1.tcspanh": "ᱠᱤᱱᱤᱡᱤᱡ ᱨᱮᱭᱟᱜ GSTIN ᱠᱷᱚᱱ ᱟᱡ ᱛᱮ ᱦᱟᱛᱟᱣᱚᱜᱼᱟ᱾ ᱴᱷᱤᱠ PAN ᱵᱟᱹᱱᱩᱜ ᱠᱷᱟᱱ TCS ᱵᱟᱹᱲᱛᱤ ᱨᱮᱴ ᱨᱮ ᱞᱟᱹᱜᱩᱜᱼᱟ (ᱥᱮᱠᱥᱚᱱ 397(2)) ᱟᱨ ᱵᱮᱱᱟᱣ ᱨᱮᱭᱟᱜ ᱰᱤᱠᱞᱮᱨᱮᱥᱚᱱ ᱵᱟᱝ ᱢᱟᱱᱟᱣᱚᱜᱼᱟ᱾",
  "b1.tcsnr": "ᱠᱤᱱᱤᱡᱤᱡ ᱫᱚ ᱵᱤᱫᱮᱥᱤ ᱠᱟᱱᱟᱭ ᱟᱨ ᱵᱷᱟᱨᱚᱛ ᱨᱮ ᱚᱱᱟᱜ ᱵᱮᱯᱟᱨ ᱴᱷᱟᱶ ᱵᱟᱹᱱᱩᱜᱼᱟ (PAN ᱵᱮᱜᱚᱨ ᱵᱟᱹᱲᱛᱤ ᱨᱮᱴ ᱵᱟᱝ ᱞᱟᱹᱜᱩᱜᱼᱟ)",
  "b1.tcsnopan": "ᱠᱤᱱᱤᱡᱤᱡ ᱨᱮᱭᱟᱜ ᱴᱷᱤᱠ PAN ᱵᱟᱹᱱᱩᱜᱼᱟ: TCS {r}% (ᱨᱮᱴ ᱨᱮᱭᱟᱜ ᱵᱟᱨ ᱜᱩᱬ ᱥᱮ 5%, ᱡᱟᱦᱟᱸ ᱵᱟᱹᱲᱛᱤ, 20% ᱦᱟᱹᱵᱤᱡ, ᱥᱮᱠᱥᱚᱱ 397(2))᱾",
  "b1.repeat": "ᱱᱚᱶᱟ ᱵᱤᱞ ᱫᱚᱦᱲᱟ ᱢᱮ",
  "b1.rep_no": "ᱫᱚᱦᱲᱟ ᱵᱟᱝ",
