  "b1.rep_q": "ᱡᱚᱛᱚ ᱯᱮ ᱪᱟᱸᱫᱚ",
  "b1.reph": "ᱟᱡ ᱛᱮ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱵᱮᱱᱟᱣᱚᱜᱼᱟ: Nivesh Sahayak ᱮᱯ ᱨᱮ ᱵᱮᱱᱟᱣ ᱞᱟᱹᱜᱤᱫ ᱠᱚᱯᱤ ᱨᱮᱭᱟᱜ ᱞᱤᱥᱴ ᱦᱤᱡᱩᱜᱼᱟ, ᱟᱢ ᱴᱮᱯ ᱠᱟᱛᱮ ᱵᱮᱱᱟᱣᱟᱢ᱾",
