  "b1.rep_t": "ᱫᱚᱦᱲᱟ ᱵᱤᱞ",
  "b1.rep_p": "\"ᱱᱚᱶᱟ ᱵᱤᱞ ᱫᱚᱦᱲᱟ ᱢᱮ\" ᱥᱟᱶ ᱥᱮᱣ ᱟᱠᱟᱱ ᱵᱤᱞ᱾ ᱞᱟᱹᱠᱛᱤ ᱠᱚᱯᱤ ᱨᱮ ᱴᱤᱠ ᱮᱢ ᱟᱨ ᱵᱚᱴᱚᱢ ᱤᱫᱤ ᱢᱮ; ᱡᱚᱛᱚ ᱠᱚᱯᱤ ᱛᱟᱭᱚᱢ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱱᱚᱢᱵᱚᱨ ᱟᱨ ᱩᱫᱩᱜ ᱟᱠᱟᱱ ᱢᱟᱦᱟᱸ ᱧᱟᱢᱟ᱾ ᱟᱢᱟᱜ ᱴᱮᱯ ᱵᱮᱜᱚᱨ ᱪᱮᱫ ᱦᱚᱸ ᱵᱟᱝ ᱵᱮᱱᱟᱣᱚᱜᱼᱟ᱾",
