  "b1.rep_how": "ᱵᱤᱞ ᱫᱚᱦᱲᱟ ᱞᱟᱹᱜᱤᱫ ᱚᱱᱟ ᱤᱱᱵᱷᱚᱭᱮᱥ ᱢᱮᱠᱚᱨ ᱨᱮ ᱡᱷᱤᱡ ᱢᱮ ᱟᱨ \"ᱱᱚᱶᱟ ᱵᱤᱞ ᱫᱚᱦᱲᱟ ᱢᱮ\" ᱨᱮ \"ᱡᱚᱛᱚ ᱪᱟᱸᱫᱚ\" ᱥᱮ \"ᱡᱚᱛᱚ ᱯᱮ ᱪᱟᱸᱫᱚ\" ᱵᱟᱪᱷᱟᱣ ᱢᱮ᱾",
