  "b1.binp": "ᱚᱪᱚᱜ ᱟᱠᱟᱱ ᱵᱤᱡᱱᱮᱥ, ᱯᱟᱨᱴᱤ, ᱟᱭᱴᱚᱢ ᱟᱨ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱱᱚᱸᱰᱮ {n} ᱫᱤᱱ ᱛᱟᱦᱮᱸᱱᱟ, ᱛᱟᱭᱚᱢ ᱡᱟᱣᱜᱮ ᱞᱟᱹᱜᱤᱫ ᱪᱟᱞᱟᱜᱼᱟ᱾ ᱨᱤᱥᱴᱚᱨ ᱞᱮᱠᱷᱟᱱ ᱢᱟᱲᱟᱝ ᱞᱮᱠᱟ ᱨᱩᱣᱟᱹᱲ ᱦᱤᱡᱩᱜᱼᱟ᱾",
