  "b1.binned": "ᱨᱤᱥᱟᱭᱤᱠᱮᱞ ᱵᱤᱱ ᱨᱮ ᱪᱟᱞᱟᱜ ᱮᱱᱟ᱾ 30 ᱫᱤᱱ ᱦᱟᱹᱵᱤᱡ ᱨᱤᱥᱴᱚᱨ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
