  "b1.nolog": "ᱱᱤᱛ ᱦᱟᱹᱵᱤᱡ ᱪᱮᱫ ᱦᱚᱸ ᱵᱚᱫᱚᱞ ᱚᱞ ᱵᱟᱝ ᱦᱩᱭ ᱟᱠᱟᱱᱟ᱾",
  "b1.thisdev": "ᱱᱚᱶᱟ ᱰᱤᱵᱷᱟᱭᱤᱥ",
  "b1.logp": "ᱡᱟᱦᱟᱱ Nivesh Sahayak ᱥᱟᱭᱤᱴ ᱨᱮ ᱵᱤᱡᱱᱮᱥ, ᱯᱟᱨᱴᱤ, ᱟᱭᱴᱚᱢ ᱥᱮ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱥᱮᱞᱮᱫ, ᱵᱚᱫᱚᱞ, ᱚᱪᱚᱜ ᱥᱮ ᱨᱤᱥᱴᱚᱨ ᱞᱮᱠᱷᱟᱱ ᱢᱟᱦᱟᱸ, ᱚᱠᱛᱚ, ᱧᱩᱛᱩᱢ ᱟᱨ ᱪᱮᱫ ᱵᱚᱫᱚᱞ ᱮᱱᱟ ᱱᱚᱸᱰᱮ ᱚᱞᱚᱜᱼᱟ᱾ ᱱᱚᱶᱟ ᱮᱱᱴᱨᱤ ᱵᱚᱫᱚᱞ ᱥᱮ ᱚᱪᱚᱜ ᱵᱟᱝ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
  "b1.logrule": "1 ᱮᱯᱨᱤᱞ 2023 ᱠᱷᱚᱱ ᱠᱚᱢᱯᱟᱱᱤ ᱠᱚ ᱱᱚᱶᱟ ᱞᱮᱠᱟᱱ ᱚᱰᱤᱴ ᱴᱨᱮᱞ ᱫᱚᱦᱚᱭᱤᱡ ᱮᱠᱟᱣᱩᱱᱴᱥ ᱥᱚᱯᱷᱴᱣᱮᱭᱟᱨ ᱵᱮᱵᱷᱟᱨ ᱞᱟᱹᱠᱛᱤᱭᱟ (ᱠᱚᱢᱯᱟᱱᱤᱡ (ᱮᱠᱟᱣᱩᱱᱴᱥ) ᱨᱩᱞᱥ 2014, ᱨᱩᱞ 3(1))᱾ ᱱᱚᱶᱟ ᱱᱚᱶᱟ ᱵᱽᱨᱟᱣᱡᱟᱨ ᱟᱨ ᱟᱢᱟᱜ ᱵᱮᱠᱟᱯ ᱯᱷᱟᱭᱤᱞ ᱨᱮ ᱛᱟᱦᱮᱸᱱᱟ᱾",
