  "b1.h_lock": "ᱱᱚᱶᱟ ᱫᱤᱱ ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ ᱢᱟᱦᱟᱸ ᱨᱮᱭᱟᱜ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱡᱟᱦᱟᱱ ᱥᱟᱭᱤᱴ ᱨᱮ ᱥᱮᱞᱮᱫ, ᱵᱚᱫᱚᱞ ᱥᱮ ᱚᱪᱚᱜ ᱵᱟᱝ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ (ᱯᱮᱢᱮᱱᱴ ᱧᱟᱢ ᱪᱤᱱᱦᱟᱹ ᱪᱟᱞᱟᱜ ᱛᱟᱦᱮᱸᱱᱟ)᱾ GST ᱨᱤᱴᱟᱨᱱ ᱵᱷᱚᱨᱟᱣ ᱥᱮ ᱦᱤᱥᱟᱹᱵ ᱵᱚᱱᱫᱚ ᱛᱟᱭᱚᱢ ᱵᱮᱵᱷᱟᱨ ᱢᱮ᱾",
  "b1.lockc": "{d} ᱞᱟᱦᱟ ᱨᱮᱭᱟᱜ ᱢᱟᱦᱟᱸ ᱨᱮᱭᱟᱜ ᱡᱚᱛᱚ ᱰᱚᱠᱭᱩᱢᱮᱱᱴ ᱞᱚᱠ ᱥᱮ? ᱱᱚᱶᱟ ᱢᱟᱦᱟᱸ ᱚᱪᱚᱜ ᱦᱟᱹᱵᱤᱡ ᱵᱚᱫᱚᱞ ᱵᱟᱝ ᱫᱟᱲᱮᱭᱟᱜᱼᱟ᱾",
