  "b2.fah": "ᱢᱮᱥᱤᱱ, ᱠᱚᱢᱯᱤᱭᱩᱴᱟᱨ, ᱯᱷᱟᱨᱱᱤᱪᱟᱨ, ᱜᱟᱹᱰᱤ ᱟᱨ ᱚᱲᱟᱜ ᱡᱟᱦᱟᱸ ᱟᱢᱟᱜ ᱵᱮᱯᱟᱨ ᱟᱭᱢᱟ ᱥᱮᱨᱢᱟ ᱵᱮᱵᱷᱟᱨᱟ᱾ ᱨᱮᱡᱤᱥᱴᱟᱨ ᱡᱚᱛᱚ ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱦᱤᱥᱟᱹᱵ ᱮᱫᱟᱭ; ᱟᱢ ᱢᱤᱫ ᱴᱮᱯ ᱛᱮ ᱠᱷᱟᱛᱟ ᱨᱮ ᱫᱚᱦᱚᱭ ᱢᱮ᱾",
