  "b2.fadup": "{n} ᱧᱩᱛᱩᱢ ᱨᱮᱭᱟᱜ ᱮᱥᱮᱴ ᱢᱟᱲᱟᱝ ᱠᱷᱚᱱ ᱥᱮᱣ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱱᱚᱶᱟ ᱮᱴᱟᱜ ᱧᱩᱛᱩᱢ ᱮᱢ ᱢᱮ (ᱡᱮᱞᱮᱠᱟ ᱢᱤᱫ ᱱᱚᱢᱵᱚᱨ ᱥᱮᱞᱮᱫ ᱢᱮ)᱾",
  "b2.fasold": "ᱱᱚᱶᱟ ᱮᱥᱮᱴ ᱨᱮᱭᱟᱜ ᱟᱠᱨᱤᱧ ᱥᱮᱣ ᱢᱮᱱᱟᱜᱼᱟ᱾ ᱢᱟᱲᱟᱝ ᱟᱠᱨᱤᱧ ᱚᱪᱚᱜ ᱢᱮ᱾",
  "b2.itblock": "ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ, FY {fy}",
