  "b2.addhalf": "ᱥᱮᱞᱮᱫ (180 ᱫᱤᱱ ᱠᱷᱚᱱ ᱠᱚᱢ)",
  "b2.sales": "ᱟᱠᱨᱤᱧ ᱴᱟᱠᱟ",
  "b2.dep": "ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ",
  "b2.closewdv": "ᱠᱞᱚᱡᱤᱝ WDV",
  "b2.gain": "ᱞᱟᱵᱷ {a}: ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱠᱩᱠᱞᱤ ᱢᱮ",
  "b2.farules": "ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱪᱮᱫ ᱞᱮᱠᱟ ᱦᱤᱥᱟᱹᱵᱚᱜᱼᱟ",
  "b2.farule1": "ᱠᱷᱟᱛᱟ ᱨᱮᱭᱟᱜ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱠᱚᱢᱯᱟᱱᱤᱡ ᱮᱠᱴ, 2013 ᱨᱮᱭᱟᱜ ᱥᱤᱰᱤᱭᱩᱞ II ᱞᱮᱠᱟᱛᱮ: ᱡᱚᱛᱚ ᱞᱮᱠᱟᱱ ᱮᱥᱮᱴ ᱨᱮᱭᱟᱜ ᱵᱮᱵᱷᱟᱨ ᱚᱠᱛᱚ ᱢᱮᱱᱟᱜᱼᱟ (ᱡᱮᱞᱮᱠᱟ ᱠᱚᱢᱯᱤᱭᱩᱴᱟᱨ 3 ᱥᱮᱨᱢᱟ, ᱯᱷᱟᱨᱱᱤᱪᱟᱨ 10 ᱥᱮᱨᱢᱟ, ᱯᱞᱟᱱᱴ ᱟᱨ ᱢᱮᱥᱤᱱᱟᱨᱤ 15 ᱥᱮᱨᱢᱟ, ᱠᱟᱨ 8 ᱥᱮᱨᱢᱟ), ᱵᱟᱠᱤ ᱫᱟᱢ ᱥᱟᱫᱷᱟᱨᱚᱬ ᱛᱮ ᱫᱟᱢ ᱨᱮᱭᱟᱜ 5% ᱠᱷᱚᱱ ᱵᱟᱹᱲᱛᱤ ᱵᱟᱝ, ᱟᱨ ᱥᱮᱨᱢᱟ ᱛᱟᱞᱟ ᱨᱮ ᱥᱮᱞᱮᱫ ᱥᱮ ᱟᱠᱨᱤᱧ ᱮᱥᱮᱴ ᱨᱮ ᱵᱮᱵᱷᱟᱨ ᱫᱤᱱ ᱨᱮᱭᱟᱜ ᱜᱮ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ᱾ ᱥᱴᱨᱮᱴ ᱞᱟᱭᱤᱱ (SLM: ᱡᱚᱛᱚ ᱥᱮᱨᱢᱟ ᱥᱟᱢᱟᱱ ᱴᱟᱠᱟ) ᱥᱮ ᱨᱤᱴᱮᱱ ᱰᱟᱣᱩᱱ ᱵᱷᱮᱞᱭᱩ (WDV: ᱵᱟᱠᱤ ᱴᱟᱠᱟ ᱨᱮ ᱴᱷᱤᱠ ᱨᱮᱴ) ᱵᱟᱪᱷᱟᱣ ᱢᱮ᱾ ᱯᱨᱚᱯᱨᱟᱭᱴᱚᱨ ᱟᱨ ᱯᱷᱟᱨᱢ ᱡᱟᱹᱥᱛᱤ ᱱᱚᱶᱟ ᱦᱚᱨ ᱵᱮᱵᱷᱟᱨᱟ ᱠᱚ; ᱴᱷᱤᱠ ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱮ ᱠᱟᱹᱴᱤᱡ ᱟ᱾",
  "b2.farule2": "ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱡᱚᱛᱚ ᱵᱞᱚᱠ ᱨᱮᱭᱟᱜ ᱟᱞᱟᱜ ᱦᱤᱥᱟᱹᱵᱚᱜᱼᱟ: ᱵᱞᱚᱠ ᱨᱮᱴ ᱨᱮ ᱨᱤᱴᱮᱱ ᱰᱟᱣᱩᱱ ᱵᱷᱮᱞᱭᱩ (ᱡᱮᱞᱮᱠᱟ ᱯᱞᱟᱱᱴ ᱟᱨ ᱢᱮᱥᱤᱱᱟᱨᱤ 15%, ᱯᱷᱟᱨᱱᱤᱪᱟᱨ 10%, ᱠᱚᱢᱯᱤᱭᱩᱴᱟᱨ 40%), ᱥᱮᱨᱢᱟ ᱨᱮ 180 ᱫᱤᱱ ᱠᱷᱚᱱ ᱠᱚᱢ ᱵᱮᱵᱷᱟᱨ ᱮᱥᱮᱴ ᱨᱮ ᱵᱟᱨᱥᱮ ᱨᱮᱴ, ᱟᱨ ᱟᱠᱨᱤᱧ ᱴᱟᱠᱟ ᱵᱞᱚᱠ ᱠᱷᱚᱱ ᱠᱚᱢᱚᱜᱼᱟ᱾ ᱱᱚᱶᱟ ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱨᱤᱴᱟᱨᱱ ᱞᱟᱹᱜᱤᱫ ᱜᱮ, ᱠᱷᱟᱛᱟ ᱨᱮ ᱡᱟᱦᱟᱸᱭ ᱚᱠᱛᱚ ᱵᱟᱝ ᱫᱚᱦᱚᱭᱚᱜᱼᱟ᱾ ᱯᱩᱨᱟᱹᱣ ᱨᱮᱴ ᱥᱟᱫᱷᱟᱨᱚᱬ ᱵᱞᱚᱠ ᱨᱮᱴ ᱠᱟᱱᱟ: ᱟᱢᱟᱜ ᱮᱠᱟᱣᱩᱱᱴᱮᱱᱴ ᱥᱟᱞᱟᱜ ᱴᱷᱤᱠ ᱢᱮ, ᱟᱥᱚᱞ ᱛᱮ 1 ᱮᱯᱨᱤᱞ 2026 ᱠᱷᱚᱱ ᱤᱱᱠᱟᱢ-ᱴᱮᱠᱥ ᱮᱠᱴ, 2025 ᱞᱟᱛᱟᱨ ᱥᱮᱨᱢᱟ ᱠᱚ ᱞᱟᱹᱜᱤᱫ᱾",
  "b2.farule3": "ᱟᱢ 'ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱫᱚᱦᱚᱭ ᱢᱮ' ᱚᱛᱟᱭ ᱠᱷᱟᱱ ᱜᱮ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱠᱷᱟᱛᱟ ᱨᱮ ᱪᱟᱞᱟᱜᱼᱟ: ᱥᱮᱨᱢᱟ ᱨᱮᱭᱟᱜ ᱢᱩᱪᱟᱹᱫ ᱫᱤᱱ (ᱥᱮ ᱛᱟᱞᱟ ᱨᱮ ᱛᱮᱦᱮᱧ) ᱨᱮᱭᱟᱜ ᱡᱟᱨᱱᱟᱞ ᱮᱱᱴᱨᱤ ᱰᱮᱯᱨᱤᱥᱤᱭᱮᱥᱚᱱ ᱰᱮᱵᱤᱴ ᱟᱨ ᱡᱚᱛᱚ ᱮᱥᱮᱴ ᱠᱚᱢ ᱮᱫᱟᱭ᱾ ᱛᱟᱭᱚᱢ ᱮᱥᱮᱴ ᱵᱚᱫᱚᱞ ᱠᱷᱟᱱ ᱫᱚᱦᱲᱟ ᱫᱚᱦᱚᱭ ᱢᱮ, ᱯᱷᱟᱨᱟᱠ ᱜᱮ ᱥᱮᱞᱮᱫᱚᱜᱼᱟ᱾",
  "b2.k_bldg_off": "ᱚᱲᱟᱜ: ᱚᱯᱷᱤᱥ ᱥᱮ ᱫᱚᱠᱟᱱ",
