  "hp.btn": "ᱜᱚᱲᱚ: {what}",
  "hp.biz": "ᱪᱮᱛᱟᱱ ᱨᱮ ᱪᱷᱟᱯᱟ ᱦᱩᱭᱩᱜ ᱟᱢᱟᱜ ᱵᱤᱡᱱᱮᱥ ᱵᱤᱵᱨᱚᱬ᱾ ᱥᱩᱡᱷᱟᱹᱣ ᱠᱷᱚᱱ ᱥᱮᱣ ᱠᱟᱱ ᱵᱤᱡᱱᱮᱥ ᱵᱟᱪᱷᱟᱣ ᱢᱮ, ᱥᱮ ᱢᱤᱫ ᱫᱷᱟᱣ ᱚᱞ ᱢᱮ, ᱛᱟᱭᱚᱢ ᱞᱟᱹᱜᱤᱫ ᱥᱮᱣᱜᱟ᱾",
  "hp.details": "ᱱᱚᱢᱵᱚᱨ ᱟᱨ ᱛᱟᱨᱤᱠᱷ᱾ ᱡᱚᱛᱚ ᱯᱷᱟᱭᱤᱱᱮᱱᱥᱤᱭᱟᱞ ᱥᱮᱨᱢᱟ ᱨᱮ ᱱᱚᱢᱵᱚᱨ ᱟᱡ ᱛᱮ ᱵᱟᱲᱦᱟᱣᱜᱟ; ᱟᱢᱟᱜ ᱟᱡᱟᱜ ᱥᱤᱨᱤᱡᱽ ᱢᱮᱱᱟᱜ ᱠᱷᱟᱱ ᱵᱚᱫᱚᱞ ᱫᱟᱲᱮᱭᱟᱜᱼᱟᱢ᱾",
  "hp.billto": "ᱡᱟᱦᱟᱸ ᱴᱷᱮᱱ ᱵᱤᱞ ᱮᱢ ᱠᱟᱱᱟ᱾ ᱧᱩᱛᱩᱢ ᱚᱞ ᱮᱦᱚᱵ ᱠᱟᱛᱮ ᱥᱮᱣ ᱠᱟᱱ ᱜᱨᱟᱦᱟᱠ ᱵᱟᱪᱷᱟᱣ ᱢᱮ, ᱥᱮ ᱱᱟᱣᱟ ᱚᱞ ᱢᱮ᱾ GSTIN ᱛᱮ ᱥᱴᱮᱴ ᱯᱮᱨᱮᱡᱜᱟ; ᱥᱴᱮᱴ ᱛᱮ CGST+SGST ᱥᱮ IGST ᱴᱷᱤᱠ ᱦᱩᱭᱩᱜᱼᱟ᱾",
  "hp.vendor": "ᱡᱟᱦᱟᱸ ᱥᱚᱯᱞᱟᱭᱟᱨ ᱴᱷᱮᱱ ᱚᱨᱰᱟᱨ ᱮᱢ ᱠᱟᱱᱟ᱾ ᱥᱮᱣ ᱠᱟᱱ ᱥᱚᱯᱞᱟᱭᱟᱨ ᱵᱟᱪᱷᱟᱣ ᱢᱮ ᱥᱮ ᱱᱟᱣᱟ ᱚᱞ ᱢᱮ᱾",
  "hp.supplier": "ᱨᱮᱡᱤᱥᱴᱨᱮᱥᱚᱱ ᱵᱟᱹᱱᱩᱜ ᱦᱚᱲ ᱠᱷᱚᱱ ᱠᱤᱨᱤᱧ ᱞᱮᱫᱟ᱾ ᱱᱚᱶᱟ ᱥᱮᱞᱯᱷ ᱤᱱᱵᱷᱚᱭᱤᱥ ᱨᱮ GST ᱨᱤᱵᱷᱟᱨᱥ ᱪᱟᱨᱡᱽ ᱛᱮ ᱟᱢ ᱟᱡ ᱜᱮᱢ ᱮᱢᱟ᱾",
  "hp.consignee": "ᱢᱟᱹᱞ ᱠᱤᱨᱤᱧᱤᱭᱟᱹ ᱵᱟᱹᱦᱤᱨ ᱮᱴᱟᱜ ᱡᱟᱭᱜᱟ ᱥᱮ ᱦᱚᱲ ᱴᱷᱮᱱ ᱪᱟᱞᱟᱜ ᱠᱷᱟᱱ ᱜᱮ ᱯᱮᱨᱮᱡ ᱢᱮ᱾",
  "hp.items": "ᱡᱚᱛᱚ ᱟᱭᱴᱮᱢ ᱥᱮ ᱥᱟᱨᱵᱷᱤᱥ ᱨᱮᱭᱟᱜ ᱢᱤᱫ ᱞᱟᱭᱤᱱ᱾ ᱥᱮᱣ ᱠᱟᱱ ᱟᱭᱴᱮᱢ ᱵᱟᱪᱷᱟᱣ ᱠᱷᱟᱱ ᱨᱮᱴ, HSN ᱟᱨ GST ᱯᱮᱨᱮᱡᱜᱟ, ᱥᱮ ᱱᱟᱣᱟ ᱚᱞ ᱢᱮ᱾ ᱞᱮᱠᱷᱟ × ᱨᱮᱴ ᱠᱷᱚᱱ ᱰᱤᱥᱠᱟᱣᱩᱱᱴ ᱚᱪᱚᱜ ᱠᱟᱛᱮ ᱴᱮᱠᱥᱮᱵᱚᱞ ᱜᱚᱱᱚᱝ᱾",
  "hp.notes": "ᱥᱚᱨᱛᱚ, ᱵᱮᱝᱠ ᱵᱤᱵᱨᱚᱬ ᱟᱨ ᱪᱷᱟᱯᱟ ᱥᱟᱦᱴᱟ ᱨᱮᱭᱟᱜ ᱨᱩᱯ᱾ ᱛᱟᱭᱚᱢ ᱞᱟᱹᱜᱤᱫ ᱰᱤᱯᱷᱚᱞᱴ ᱞᱮᱠᱟ ᱥᱮᱣᱜᱟ᱾",
  "hp.einv": "ᱡᱟᱦᱟᱸ ᱵᱤᱡᱱᱮᱥ ᱞᱟᱹᱜᱤᱫ ᱤ-ᱤᱱᱵᱷᱚᱭᱤᱥ ᱥᱮ ᱤ-ᱣᱮ ᱵᱤᱞ ᱞᱟᱹᱠᱛᱤ ᱜᱮᱭᱟ: ᱯᱷᱟᱭᱤᱞ ᱰᱟᱣᱩᱱᱞᱚᱰ ᱢᱮ, ᱥᱚᱨᱠᱟᱨᱤ ᱯᱚᱨᱴᱟᱞ ᱨᱮ ᱟᱢᱟᱜ ᱞᱚᱜᱤᱱ ᱛᱮ ᱟᱯᱞᱚᱰ ᱢᱮ, ᱛᱟᱭᱚᱢ ᱛᱮ ᱛᱮᱞᱟ ᱱᱚᱰᱮ ᱞᱚᱰ ᱢᱮ᱾",
  "hp.exp": "ᱮᱠᱥᱯᱚᱨᱴ ᱞᱟᱹᱜᱤᱫ: ᱥᱤᱯᱤᱝ ᱵᱤᱞ, ᱯᱚᱨᱴ ᱟᱨ ᱠᱟᱨᱮᱱᱥᱤ᱾ ᱮᱠᱥᱯᱚᱨᱴ ᱫᱚ ᱡᱤᱨᱚ-ᱨᱮᱴᱮᱰ: LUT ᱢᱮᱱᱟᱜ ᱠᱷᱟᱱ GST ᱵᱟᱝ ᱞᱟᱹᱜᱤᱫᱼᱟ; ᱵᱟᱹᱱᱩᱜ ᱠᱷᱟᱱ IGST ᱮᱢ ᱠᱟᱛᱮ ᱨᱤᱯᱷᱟᱱᱰ ᱧᱟᱢᱚᱜᱼᱟ᱾",
  "hp.s.from": "ᱡᱟᱦᱟᱸ ᱟᱢ ᱴᱟᱠᱟᱭ ᱮᱢ ᱞᱮᱫᱟᱢ᱾ ᱥᱮᱣ ᱠᱟᱱ ᱜᱨᱟᱦᱟᱠ ᱵᱟᱪᱷᱟᱣ ᱢᱮ ᱥᱮ ᱧᱩᱛᱩᱢ ᱚᱞ ᱢᱮ᱾",
