  "hp.s.to": "ᱡᱟᱦᱟᱸ ᱴᱷᱮᱱ ᱟᱢ ᱴᱟᱠᱟ ᱮᱢ ᱞᱮᱫᱟ᱾ ᱥᱮᱣ ᱠᱟᱱ ᱥᱚᱯᱞᱟᱭᱟᱨ ᱵᱟᱪᱷᱟᱣ ᱢᱮ ᱥᱮ ᱧᱩᱛᱩᱢ ᱚᱞ ᱢᱮ᱾",
