  "hp.s.sign": "ᱮᱢᱤᱭᱟᱹ, ᱦᱟᱛᱟᱣᱤᱭᱟᱹ ᱟᱨ ᱢᱟᱱᱟᱣᱤᱭᱟᱹ ᱨᱮᱭᱟᱜ ᱧᱩᱛᱩᱢ᱾ ᱛᱤ ᱛᱮ ᱥᱟᱭᱤᱱ ᱞᱟᱹᱜᱤᱫ ᱠᱷᱟᱞᱤ ᱟᱲᱟᱜ ᱢᱮ᱾",
